#!/bin/sh
# Build and run the keys module's host-side tests, for both key maps (device
# and emulator), against a checkout of nyx-lib's public headers
# (NYX_LIB_INCLUDE, default ../nyx-lib/include/public).
# Extra compiler flags (sanitizers, say) go in CFLAGS.
set -e
here=$(cd "$(dirname "$0")" && pwd)
top=$(cd "$here/../../.." && pwd)
nyxinc=${NYX_LIB_INCLUDE:-$top/../nyx-lib/include/public}
build=${BUILD_DIR:-/tmp}
# nyx_version.h is generated by nyx-lib's CMake; make one from the template.
mkdir -p "$build/nyxgen/nyx/common"
sed -e 's/@NYX_API_VERSION_MAJOR@/7/' -e 's/@NYX_API_VERSION_MINOR@/0/' \
    "$nyxinc/nyx/common/nyx_version.h.in" > "$build/nyxgen/nyx/common/nyx_version.h"

for variant in device emulator; do
    out=$build/test_keys_lookup_$variant
    define=
    [ "$variant" = emulator ] && define=-DKEYS_EMULATOR
    # shellcheck disable=SC2046,SC2086  # pkg-config output and CFLAGS are flag lists
    ${CC:-cc} -std=gnu99 -Wall -Wextra -Wno-unused-parameter $define \
        ${CFLAGS:-} \
        -I"$top/src/system/tests/stubs" -I"$build/nyxgen" -I"$nyxinc" -I"$top/include/internal" \
        $(pkg-config --cflags glib-2.0) \
        "$here/test_keys_lookup.c" $(pkg-config --libs glib-2.0) -o "$out"
    echo "== test_keys_lookup ($variant)"
    "$out" "$@"
done
